import{_ as a,o,c as t,a5 as r}from"./chunks/framework.BwlBv862.js";const p=JSON.parse('{"title":"登录 Cloud 账户","description":"","frontmatter":{"title":"登录 Cloud 账户","docId":"user.cloud.account","translationKey":"user.cloud.account","locale":"zh","audience":"user","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"02b7718e7fc7b2a53b68ee1c6e19e622608a6fdfc7eac553879c474ca69ea74b","translationRevision":"dcdf6b0e0597904e86b677257bceda1e83a272fbe55075253c580e829a37db83","order":10},"headers":[],"relativePath":"zh/user/cloud/account.md","filePath":"zh/user/cloud/account.md","lastUpdated":1794611623000}'),i={name:"zh/user/cloud/account.md"};function n(l,e,s,c,d,u){return o(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="sign-in-to-your-cloud-account" tabindex="-1">登录 Cloud 账户 <a class="header-anchor" href="#sign-in-to-your-cloud-account" aria-label="Permalink to &quot;登录 Cloud 账户 {#sign-in-to-your-cloud-account}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">目标与前置条件 <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;目标与前置条件 {#goal-and-prerequisites}&quot;">​</a></h2><p>将桌面应用连接到已配置的 Cloud 服务，以使用基于账户的目录与协作操作。你需要网络、系统浏览器及可用的操作系统凭据存储。未连接 Cloud 时仍可使用本地编辑；Cloud 会话不能验证 TikTok LIVE 连接。</p><h2 id="sign-in-and-verify-identity" tabindex="-1">登录并验证身份 <a class="header-anchor" href="#sign-in-and-verify-identity" aria-label="Permalink to &quot;登录并验证身份 {#sign-in-and-verify-identity}&quot;">​</a></h2><ol><li>打开 <strong>设置 → 账户</strong>。开始另一轮登录前，先阅读当前状态。</li><li>选择 <strong>登录</strong>。桌面程序会启动本地回调接收器，并在系统浏览器中打开已配置的登录页面。</li><li>完成服务的登录流程，然后返回 TikTools。如果浏览器未打开，请使用应用为本次尝试显示的登录 URL。该 URL 应保密，不要公开发布。</li><li>等待账户状态变为已登录。打开私有目录或团队前，确认显示的名称或邮箱。</li><li>状态报告错误时，展开账户诊断信息。使用 <strong>取消</strong> 放弃未完成的尝试，避免同时保留多次活动尝试。</li><li>在共用电脑上使用完毕后，选择 <strong>退出登录</strong>，并验证账户状态已改变。</li></ol><p>原生宿主管理会话令牌。凭据通过操作系统凭据存储保存，前端仅保留非秘密状态。安全存储不可用时，不会退回明文文件存储。复制数据文件夹不会得到可携带的已登录会话。</p><h2 id="expected-result-and-status" tabindex="-1">预期结果与状态 <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to &quot;预期结果与状态 {#expected-result-and-status}&quot;">​</a></h2><p>启用 Cloud 身份验证构建的宿主支持原生登录、恢复及退出。已配置账户可在重启时恢复，并向服务重新验证。未配置或不受支持的宿主，不能通过更换 TikTok Cookie 来修复。</p><p>服务登录是否可用，以及真实提供商和平台能否通过验收，取决于部署的服务与本机环境。本地验证不能证明所有生产登录路径都正常。</p><h2 id="recovery" tabindex="-1">恢复方法 <a class="header-anchor" href="#recovery" aria-label="Permalink to &quot;恢复方法 {#recovery}&quot;">​</a></h2><p>尝试已取消或过期时，关闭旧尝试后重新登录。网络或服务错误请保留诊断代码，待恢复后重试。凭据存储错误需恢复操作系统的安全存储能力；不要将 bearer 令牌粘贴到设置或支持消息中。明确同步操作见<a href="./changes.html">变更</a>，独立访问授权见<a href="./collaboration.html">协作</a>。</p><h2 id="operational-details" tabindex="-1">运行细节 <a class="header-anchor" href="#operational-details" aria-label="Permalink to &quot;运行细节 {#operational-details}&quot;">​</a></h2><p>退出登录先删除本地凭据并清空账户上下文，再尽力尝试服务器撤销。界面显示已退出只确认本地移除，不证明网络故障时远程令牌已撤销。若服务提供会话管理，可在那里检查。退出或切换已知账户前请导出 Diagnostics，因为该界面历史会清空。TikTok cookie 与远程宿主会话是独立身份。</p>',13)])])}const f=a(i,[["render",n]]);export{p as __pageData,f as default};
